31	// boundaryRangeCase pins one non-octet-aligned network: its canonical form
32	// plus the addresses that must and must not be admitted.
33	type boundaryRangeCase struct {
34		name      string
35		spelled   string // one host-spelled form of the network
36		canonical string
37		inside    []string
38		outside   []string
39	}
