88	// TestSourceCIDRFilterNonOctetBoundaryMembership pins the exact admitted
89	// range of each boundary network against the normalized-address strings the
90	// filter actually compares.
91	func TestSourceCIDRFilterNonOctetBoundaryMembership(t *testing.T) {
92		for _, tc := range boundaryRanges {
93			t.Run(tc.name, func(t *testing.T) {
94				f, err := ParseSourceCIDRFilter(tc.spelled)
95				if err != nil {
96					t.Fatalf("ParseSourceCIDRFilter(%q) unexpected error: %v", tc.spelled, err)
97				}
