99					t.Fatalf("ParseSourceCIDRFilter(%q).String() = %q, want %q", tc.spelled, got, tc.canonical)
100				}
101				for _, ip := range tc.inside {
102					if !f.admits(ip) {
103						t.Errorf("%s must admit range address %q", tc.canonical, ip)
104					}
