234	// TestSourceCIDRFilterSlash31KeepsBothAddresses pins the two-address network:
235	// 192.0.2.3/31 admits both 192.0.2.2 and 192.0.2.3 — neither address is
236	// excluded as a network or broadcast address — while the immediate neighbors
237	// 192.0.2.1 and 192.0.2.4 are dropped. The same network spelled with its
238	// other host address selects identically.
239	func TestSourceCIDRFilterSlash31KeepsBothAddresses(t *testing.T) {
240		input := strings.Join([]string{
241			`{"timestamp":` + validTS + `,"action":"below","source_ip":"192.0.2.1"}`,             // line 1 dropped
242			`{"timestamp":` + validTS + `,"action":"low-of-pair","source_ip":"192.0.2.2"}`,       // line 2 admitted
243			`{"timestamp":` + validTS + `,"action":"high-of-pair","src_ip":"192.0.2.3"}`,         // line 3 admitted via alias
244			`{"timestamp":` + validTS + `,"action":"mapped-low","source_ip":"::ffff:192.0.2.2"}`, // line 4 admitted
245			`{"timestamp":` + validTS + `,"action":"above","source_ip":"192.0.2.4"}`,             // line 5 dropped
246		}, "\n") + "\n"
247	
248		var outputs []string
249		for _, spelled := range []string{"192.0.2.3/31", "192.0.2.2/31"} {
250			filter, err := ParseSourceCIDRFilter(spelled)
251			if err != nil {
252				t.Fatal(err)
253			}
254			results, failures := runNormalizeFiltered(t, input, &filter)
255			if failures != 0 {
256				t.Fatalf("filter %q: an all-valid batch must have zero failures, got %d", spelled, failures)
257			}
258			if len(results) != 3 {
259				t.Fatalf("filter %q: both /31 addresses and the mapped spelling must survive, got %#v", spelled, results)
260			}
