595	func TestNormalizeUTCYearRangeAliases(t *testing.T) {
596		cases := []struct {
597			name  string
598			input string
599			ok    bool
600			want  string
601		}{
602			{
603				name:  "same out-of-range instant spelled twice",
604				input: `{"timestamp":"0000-01-01T00:00:00+00:01","time":"0000-01-01T00:01:00+00:02","action":"a"}`,
605				ok:    false,
606			},
607			{
608				name:  "same out-of-range instant repeated",
609				input: `{"timestamp":"9999-12-31T23:59:59-00:01","time":"9999-12-31T23:59:59-00:01","action":"a"}`,
610				ok:    false,
611			},
612			{
613				name:  "one legal value one out of range",
614				input: `{"timestamp":"0000-01-01T00:00:00Z","time":"0000-01-01T00:00:00+00:01","action":"a"}`,
615				ok:    false,
616			},
617			{
618				name:  "legal consistent values at lower edge merge",
619				input: `{"timestamp":"0000-01-01T00:00:00Z","time":"0000-01-01T00:01:00+00:01","action":"a"}`,
620				ok:    true,
621				want:  "0000-01-01T00:00:00Z",
622			},
623			{
624				name:  "legal consistent values at upper edge merge",
625				input: `{"timestamp":"9999-12-31T23:59:59Z","time":"9999-12-31T23:58:59-00:01","action":"a"}`,
626				ok:    true,
627				want:  "9999-12-31T23:59:59Z",
628			},
629			{
630				name:  "distinct legal instants still conflict",
631				input: `{"timestamp":"0000-01-01T00:01:00+00:01","time":"0000-01-01T00:02:00+00:01","action":"a"}`,
632				ok:    false,
633			},
634		}
635		for _, tc := range cases {
636			t.Run(tc.name, func(t *testing.T) {
637				results := runNormalize(t, tc.input)
638				if tc.ok {
639					if results[0]["ok"] != true {
640						t.Fatalf("expected success, got %#v", results[0])
641					}
642					if got := eventOf(t, results[0])["timestamp"]; got != tc.want {
643						t.Fatalf("timestamp %v, want %q", got, tc.want)
644					}
645					return
646				}
647				if results[0]["ok"] != false {
648					t.Fatalf("expected failure, got %#v", results[0])
649				}
650				if _, exists := results[0]["event"]; exists {
651					t.Fatalf("failure must not emit an event")
652				}
653				msg, _ := results[0]["error"].(string)
654				if !strings.Contains(msg, FieldTimestamp) {
655					t.Fatalf("error must name %q, got %q", FieldTimestamp, msg)
656				}
657			})
658		}
659	}
