75	// runNormalizeCLIArgs is runNormalizeCLI with explicit extra arguments after
76	// the normalize subcommand, e.g. runNormalizeCLIArgs(t, r, "--source-cidr",
77	// "192.0.2.0/24").
78	func runNormalizeCLIArgs(t *testing.T, stdin io.Reader, args ...string) cliResult {
79		t.Helper()
80		cmd := exec.Command(normalizeBin, append([]string{"normalize"}, args...)...)
81		cmd.Stdin = stdin
82		var stdout, stderr bytes.Buffer
83		cmd.Stdout = &stdout
84		cmd.Stderr = &stderr
85	
86		err := cmd.Run()
87		result := cliResult{stdout: stdout.String(), stderr: stderr.String()}
88		switch {
89		case err == nil:
90			result.exitCode = 0
91		default:
92			exitErr, ok := err.(*exec.ExitError)
93			if !ok {
94				t.Fatalf("normalize process could not run: %v", err)
95			}
