101	// decodeStdoutResults parses stdout as newline-delimited JSON result
102	// objects. Any line that is not a JSON object — help text, a plain-text
103	// notice, a log fragment — fails the test, because stdout must carry
104	// machine-readable results and nothing else.
105	func decodeStdoutResults(t *testing.T, stdout string) []map[string]any {
106		t.Helper()
107		var results []map[string]any
108		decoder := json.NewDecoder(strings.NewReader(stdout))
109		for {
110			var record map[string]any
111			if err := decoder.Decode(&record); err != nil {
112				if err == io.EOF {
